def choose_address(prefix):
    prov = st.selectbox('도·광역시', list(ADDRESS_TREE), index=list(ADDRESS_TREE).index('충청남도'), key=prefix+'_prov')
    cities = ADDRESS_TREE[prov]['children']
    district = st.selectbox('시·군·구', list(cities), key=prefix+'_city_'+prov)
    node = cities[district]
    towns = node.get('children', {})
    town = st.selectbox('읍·면·동', ['전체 (대표 지점)'] + list(towns), key=prefix+'_town_'+prov+'_'+district)
    point = node if town == '전체 (대표 지점)' else towns[town]
    label = ' · '.join([prov, district] + ([] if town == '전체 (대표 지점)' else [town]))
    st.caption('선택 지역 대표 좌표예요. 최신 행정구역 변경은 반영되지 않을 수 있어요.')
    return label, (float(point['lat']), float(point['lng']))

